#!/usr/bin/env python3
"""Let the extractor load a corrected file into the records that were sent back.
Once peers have seen a source, a normal upload is refused (it would replace the records and lose the reviewers' catches), and the
Fix Record form can only add or change values, never remove a wrong key. Now the upload window offers
"Apply as corrections to sent-back records": each row is matched to an existing record by its name and replaces that record's fields
in place. Records that are approved or locked, and rows that match nothing, are reported and left alone. Nothing is added or removed,
and every change is logged with the keys that changed.
Run from the repo root. Safe to run twice."""
import os, sys, json
sys.stdout.reconfigure(errors='replace')
OPS = json.loads('[["backend/app/api/v1/routes/sources.py", "upload-corrections", "@router.patch(\\"/{source_id}/records/{record_id}\\", response_model=RecordOut)\\ndef fix_record(", "@router.post(\\"/{source_id}/upload-corrections\\")\\nasync def upload_corrections(\\n    source_id: str,\\n    request: Request,\\n    file: UploadFile = File(...),\\n    db: Session = Depends(get_db),\\n    current_user: User = Depends(get_current_user),\\n):\\n    \\"\\"\\"Load a corrected file into the records that were sent back, in place.\\n\\n    Unlike a normal upload this never replaces or removes records, so the reviewers\' catches, the checks and the history stay\\n    attached. Each row is matched to an existing record by its name; the matched record\'s fields are replaced by the row (so a key\\n    that was removed in the file is removed on the record). Records that are locked, and rows that match nothing, are reported and left alone.\\"\\"\\"\\n    source = _get_source_or_404(source_id, db, current_user)\\n    if not _is_assigned_extractor(current_user, source):\\n        raise HTTPException(status_code=403, detail=\\"Only the assigned extractor, project admin, or org admin can upload to this source\\")\\n    import os as _os, unicodedata as _ud\\n    ext = _os.path.splitext(file.filename or \\"\\")[1].lower()\\n    if ext not in (\\".json\\", \\".csv\\", \\".xlsx\\", \\".xls\\"):\\n        raise HTTPException(status_code=422, detail=\\"Corrections can be loaded from a JSON, CSV or Excel file.\\")\\n    content = await file.read()\\n    if len(content) > MAX_UPLOAD_SIZE_BYTES:\\n        raise HTTPException(status_code=413, detail=\\"That file is too large for corrections. Split it, or fix the records one by one.\\")\\n    try:\\n        rows = [r for r in _parse_rows(content, ext, file.filename or \\"\\") if isinstance(r, dict)]\\n    except Exception as e:\\n        raise HTTPException(status_code=422, detail=f\\"Could not read that file: {e}\\")\\n    if not rows:\\n        raise HTTPException(status_code=422, detail=\\"No rows found in the file.\\")\\n\\n    schema_ver = db.query(SchemaVersion).filter(SchemaVersion.schema_id == source.schema_id).order_by(SchemaVersion.version.desc()).first()\\n    schema_fields = schema_ver.definition.get(\\"fields\\", []) if schema_ver and schema_ver.definition else []\\n    records = db.query(ExtractedRecord).join(ExtractionJob).filter(ExtractionJob.source_id == source_id).all()\\n    if not records:\\n        raise HTTPException(status_code=422, detail=\\"This source has no records to correct. Use Upload Data instead.\\")\\n\\n    KEYS = (\\"canonical_name\\", \\"company_name\\", \\"segment_name\\", \\"regulation_name\\", \\"product_name\\", \\"name\\")\\n\\n    def norm(v):\\n        s = _ud.normalize(\\"NFKD\\", str(v).lower().strip())\\n        s = \\"\\".join(c for c in s if _ud.category(c) != \\"Mn\\").replace(\\"&\\", \\"and\\")\\n        return re.sub(r\\"[^a-z0-9]+\\", \\"-\\", s).strip(\\"-\\")\\n\\n    by_key: dict = {}\\n    for r in records:\\n        cands = [r.canonical_name] + [(r.extracted_fields or {}).get(k) for k in KEYS]\\n        for c in cands:\\n            if isinstance(c, str) and c.strip():\\n                by_key.setdefault(norm(c), r)\\n\\n    from app.services import record_locks as _rl\\n    updated, unchanged, locked, unmatched = [], [], [], []\\n    used: set = set()\\n    for i, row in enumerate(rows):\\n        mapped = dict(row) if ext == \\".json\\" else map_row_to_fields(row, schema_fields)\\n        if ext == \\".json\\":\\n            for fd in schema_fields:\\n                if \\"fixed_value\\" in fd:\\n                    mapped[fd[\\"name\\"]] = fd[\\"fixed_value\\"]\\n        label = next((str(mapped.get(k)) for k in KEYS if mapped.get(k)), f\\"row {i + 1}\\")\\n        rec = next((by_key[norm(mapped[k])] for k in KEYS if isinstance(mapped.get(k), str) and mapped.get(k).strip() and norm(mapped[k]) in by_key), None)\\n        if rec is None and len(rows) == 1 and len(records) == 1:\\n            rec = records[0]\\n        if rec is None or rec.id in used:\\n            unmatched.append(label)\\n            continue\\n        try:\\n            lock_override = _rl.assert_record_editable(source, rec, current_user)\\n        except HTTPException:\\n            locked.append(label)\\n            continue\\n        used.add(rec.id)\\n        before = dict(rec.extracted_fields or {})\\n        if before == mapped:\\n            unchanged.append(label)\\n            continue\\n        rec.extracted_fields = mapped\\n        ok, errs = validate_record(mapped, schema_fields)\\n        rec.is_schema_valid = ok\\n        rec.validation_errors = errs\\n        rec.extraction_confidence = ExtractionConfidence.HIGH if ok else ExtractionConfidence.FLAGGED\\n        if rec.review_status == ReviewStatus.REJECTED and ok:\\n            rec.review_status = ReviewStatus.PENDING\\n        changed_keys = sorted(k for k in set(before) | set(mapped) if (k in before) != (k in mapped) or before.get(k) != mapped.get(k))\\n        db.add(AuditLog(\\n            user_id=current_user.id, project_id=source.project_id, source_id=source.id, job_id=rec.job_id, record_id=rec.id,\\n            action=AuditAction.SOURCE_RECORD_FIXED,\\n            before_value={\\"fields\\": before},\\n            after_value={\\"fields\\": mapped, \\"changed\\": changed_keys, \\"changed_by\\": current_user.id, \\"lock_override\\": lock_override,\\n                         \\"status_at_edit\\": source.status.value, \\"via\\": \\"corrections_file\\", \\"file\\": file.filename},\\n        ))\\n        updated.append({\\"record\\": label, \\"changed\\": changed_keys})\\n    source.updated_at = datetime.now(timezone.utc)\\n    db.flush()\\n    _recompute_counts(source, db)\\n    if source.invalid_records == 0 and source.status == SourceStatus.NEEDS_FIXES:\\n        source.status = SourceStatus.READY_FOR_REVIEW\\n        source.extraction_completed_at = datetime.now(timezone.utc)\\n    db.commit()\\n    return {\\"updated\\": updated, \\"unchanged\\": unchanged, \\"locked\\": locked, \\"unmatched\\": unmatched, \\"rows\\": len(rows)}\\n\\n\\n@router.patch(\\"/{source_id}/records/{record_id}\\", response_model=RecordOut)\\ndef fix_record("], ["frontend/src/api/client.ts", "uploadCorrections:", "  uploadMulti: (id: string, files: File[], onProgress?: (pct: number) => void) => {", "  uploadCorrections: (id: string, formData: FormData) =>\\n    api.post(`/sources/${id}/upload-corrections`, formData, { headers: { \'Content-Type\': \'multipart/form-data\' }, timeout: 120000 }).then(r => r.data as { updated: { record: string; changed: string[] }[]; unchanged: string[]; locked: string[]; unmatched: string[]; rows: number }),\\n  uploadMulti: (id: string, files: File[], onProgress?: (pct: number) => void) => {"], ["frontend/src/pages/SourceDetail.tsx", "const applyCorrections", "  const [uploadWarnings, setUploadWarnings] = useState<string[]>([])\\n", "  const [uploadWarnings, setUploadWarnings] = useState<string[]>([])\\n  // An upload that would replace records already seen by peers is refused. This offers to load the same file as corrections instead.\\n  const [lockedUpload, setLockedUpload] = useState<string | null>(null)\\n  const [corrBusy, setCorrBusy] = useState(false)\\n  const [corrResult, setCorrResult] = useState<{ updated: { record: string; changed: string[] }[]; unchanged: string[]; locked: string[]; unmatched: string[] } | null>(null)\\n  const applyCorrections = async () => {\\n    if (!sourceId || !file) return\\n    setCorrBusy(true)\\n    try {\\n      const fd = new FormData(); fd.append(\'file\', file)\\n      const r = await sourcesApi.uploadCorrections(sourceId, fd)\\n      setCorrResult(r); setLockedUpload(null)\\n      toast.success(r.updated.length ? `Corrections applied to ${r.updated.length} record${r.updated.length === 1 ? \'\' : \'s\'}` : \'No record needed a change\')\\n      load()\\n    } catch (e: any) { toast.error(e?.response?.data?.detail || \\"Couldn\'t apply the corrections\\") } finally { setCorrBusy(false) }\\n  }\\n"], ["frontend/src/pages/SourceDetail.tsx", "setLockedUpload(String(err", "    } catch (err: any) {\\n      toast.error(describeUploadError(err))\\n    } finally {\\n      setUploading(false)\\n      setUploadProgress(0)\\n    }\\n  }\\n\\n  const handleFolderUpload", "    } catch (err: any) {\\n      if (err?.response?.status === 423) { setLockedUpload(String(err.response.data?.detail || \'This source is locked for bulk changes.\')); setCorrResult(null) }\\n      else toast.error(describeUploadError(err))\\n    } finally {\\n      setUploading(false)\\n      setUploadProgress(0)\\n    }\\n  }\\n\\n  const handleFolderUpload"], ["frontend/src/pages/SourceDetail.tsx", "{lockedUpload && (", "                Re-uploading replaces all {source.total_records} existing records.\\n              </div>\\n            )}\\n", "                Re-uploading replaces all {source.total_records} existing records.\\n              </div>\\n            )}\\n\\n            {lockedUpload && (\\n              <div className=\\"bg-indigo-50 border border-indigo-200 rounded-xl px-3 py-3 text-xs text-indigo-900 space-y-2\\">\\n                <p className=\\"m-0\\"><b>This file cannot replace the records.</b> {lockedUpload}</p>\\n                <p className=\\"m-0\\">You can load the same file as <b>corrections</b> instead. Each row is matched to a record by its name and updates it in place, so the reviewers\' catches stay attached. Only records that were sent back are changed.</p>\\n                <Button type=\\"button\\" size=\\"sm\\" loading={corrBusy} disabled={!file} onClick={applyCorrections}>Apply as corrections to sent-back records</Button>\\n              </div>\\n            )}\\n            {corrResult && (\\n              <div className=\\"bg-emerald-50 border border-emerald-200 rounded-xl px-3 py-3 text-xs text-emerald-900 space-y-1.5\\">\\n                <p className=\\"m-0\\"><b>{corrResult.updated.length} updated</b>{corrResult.unchanged.length ? `, ${corrResult.unchanged.length} already matched the file` : \'\'}.</p>\\n                {corrResult.updated.map(u => <p key={u.record} className=\\"m-0\\">{u.record}: {u.changed.length ? `changed ${u.changed.slice(0, 8).join(\', \')}${u.changed.length > 8 ? \'\\u2026\' : \'\'}` : \'no field changes\'}</p>)}\\n                {corrResult.locked.length > 0 && <p className=\\"m-0 text-amber-800\\">Not changed because they are locked or not sent back: {corrResult.locked.join(\', \')}</p>}\\n                {corrResult.unmatched.length > 0 && <p className=\\"m-0 text-amber-800\\">No matching record, so not added: {corrResult.unmatched.join(\', \')}</p>}\\n                <p className=\\"m-0\\">Now hand the source back for review from the source page.</p>\\n              </div>\\n            )}\\n"], ["frontend/src/pages/SourceDetail.tsx", "setLockedUpload(null); setCorrResult(null) }}", "onChange={e => { setFile(e.target.files?.[0] ?? null); setFolderFiles(null) }}", "onChange={e => { setFile(e.target.files?.[0] ?? null); setFolderFiles(null); setLockedUpload(null); setCorrResult(null) }}"]]')
ok = True

def rd(p):
    raw = open(p, 'rb').read().decode('utf-8'); return raw, ('\r\n' in raw), raw.replace('\r\n', '\n')
def wr(p, t, crlf): open(p, 'wb').write((t.replace('\n', '\r\n') if crlf else t).encode('utf-8'))

by = {}
for f, mark, anchor, new in OPS: by.setdefault(f, []).append((mark, anchor, new))
for f, steps in by.items():
    if not os.path.exists(f): print("MISSING   ", f); ok = False; continue
    raw, crlf, t = rd(f)
    for mark, anchor, new in steps:
        if mark in t: print("already   ", f.split('/')[-1], mark[:40].strip()); continue
        if t.count(anchor) != 1: print("NO MATCH  ", f, mark[:50]); ok = False; continue
        t = t.replace(anchor, new, 1); print("applied   ", f.split('/')[-1], mark[:40].strip())
    wr(f, t, crlf)
print()
print("All applied." if ok else "Some edits did not match: paste the lines above and I will fit them to your files.")
